// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    address depositor = 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001;

    function setUp() public { c = new L1Block(); }

    function testFuzz_property(
        uint64 number0,
        uint64 number1,
        uint64 ts,
        uint256 basefee,
        bytes32 h,
        uint64 seq,
        bytes32 bh,
        uint256 overhead,
        uint256 scalar
    ) public {
        // seed the state variable with a first (different) value
        vm.prank(depositor);
        c.setL1BlockValues(number0, ts, basefee, h, seq, bh, overhead, scalar);

        vm.prank(depositor);
        c.setL1BlockValues(number1, ts, basefee, h, seq, bh, overhead, scalar);

        // general rule: after a depositor call, number always reflects the latest _number argument
        assertTrue(c.number() == number1);
    }
}
